# DK RNX.  Rønne H - Nexø
#
let rn = path("d3.dk.rnx");

with detail = 3, railway = :third :narrow :g1000 :pax :removed {
    with link = "point.dk.Rønne-H", railway = :station {
        track(rn[:roh - 0.5sw, :roh + 0.5sw]);
        marker(:right :de.bf, rn[:roh] >> 0.5lt);
        slabel(:left, rn[:roh] << 0.5lt + (-1.3dt, 1.1dt),
            span(:bold, "Rønne H")
        );
    }

    with link = "line.dk.RNX" {
        track(rn[:roh + 0.49sw, :roh + 0.76km]);
        line_label(:left:e, rn[:roh + 0.75km] << 0.5lt, "RNX");
        track(rn[:roh + 0.74km, :ron - 0.49sw]);
    }

    with link = "point.dk.Rønne-Nord", railway = :station {
        track(rn[:ron - 0.5sw, :ron.ya]);
        track(
                rn[:ron - 0.51sw, :ron - 0.5sw]
            --  rn[:ron - 0.5sw + 1dl, :ron.ya] << 1ls << 1lt
        );
        marker(:right :de.bf, rn[:ron] >> 0.5lt);
        slabel(:left, rn[:ron] << 1ls << 1.5lt + (0dt, -0.8dt),
            span(:bold, "Rønne Nord")
        );
    }

    with link = "line.dk.RNX" {
        track(rn[:ron.ya - 0.1dl, :roo - 0.49sw]);
    }

    with link = "point.dk.Rønne-Østre", railway = :station {
        track(rn[:roo - 0.5sw, :roo + 0.5sw]);
        marker(:left :de.hp, rn[:roo] << 1lt);
        slabel(:right, rn[:roo] << 1lt << 1sh + (1.5dt, 0.8dt),
            "Rønne Østre"
        );
    }

    with link = "line.dk.RNX" {
        track(rn[:roo + 0.49sw, :rab + 0.1dl]);
    }

    with link = "point.dk.Rabekkeværket", railway = :station {
        marker(:left :de.anst, rn[:rab] << 0.5lt);
        slabel(:right :xsmall, rn[:rab] << 0.5lt << 1sh + (1.5dt, 0.8dt),
            "Rabekkeværket"
        );
    }

    with link = "line.dk.RNX" {
        track(rn[:rab - 0.1dl, :rab + 0.71km]);
        line_label(:right:e, rn[:rab + 0.7km] >> 0.5lt, (0dt, 0.2dt), "RNX");
        track(rn[:rab + 0.69km, :rob - 0.49sw]);
    }

    with link = "point.dk.Robbedale", railway = :station {
        track(rn[:rob - 0.5sw, :rob + 0.5sw]);
        marker(:left :de.hp, rn[:rob] << 0.5lt);
        slabel(:right, rn[:rob] << 0.5lt << 1sh + (1.5dt, 0.5dt),
            "Robbedale"
        );
    }

    with link = "line.dk.RNX" {
        track(rn[:rob + 0.49sw, :kol - 0.49sw]);
    }

    with link = "point.dk.Køllergårde", railway = :station {
        track(rn[:kol - 0.5sw, :kol + 0.5sw]);
        marker(:right :de.bf, rn[:kol] >> 0.5lt);
        slabel(:bottom, rn[:kol] >> 0.5lt >> 1sh + (-4dt, 0.3dt),
            "Køllergårde"
        );
    }

    with link = "line.dk.RNX" {
        track(rn[:kol + 0.49sw, :nyl - 0.49sw]);
    }

    with link = "point.dk.Nylars", railway = :station {
        track(rn[:nyl - 0.5sw, :nyl + 0.5sw]);
        marker(:right :de.hp, rn[:nyl] >> 0.5lt);
        slabel(:bottom, rn[:nyl] >> 0.5lt >> 1sh >> 0.3dt,
            "Nylars"
        );
    }

    with link = "line.dk.RNX" {
        track(rn[:nyl + 0.49sw, :lob - 0.49sw]);
    }

    with link = "point.dk.Lobbæk", railway = :station {
        track(rn[:lob - 0.5sw, :lob + 0.5sw]);
        marker(:right :de.bf, rn[:lob] >> 0.5lt);
        slabel(:bottom, rn[:lob] >> 0.5lt >> 1sh + (2.5dt, 0.4dt),
            "Lobbæk"
        );
    }

    with link = "line.dk.RNX" {
        track(rn[:lob + 0.49sw, :smo - 0.49sw]);
    }

    with link = "point.dk.Smørenge", railway = :station {
        track(rn[:smo - 0.5sw, :smo + 0.5sw]);
        marker(:right :de.hp, rn[:smo] >> 0.5lt);
        slabel(:left, rn[:smo] << 0.5lt + (-1dt, -0.5dt),
            "Smørenge"
        );
    }

    with link = "line.dk.RNX" {
        track(rn[:smo + 0.49sw, :smo + 0.91km]);
        line_label(:right:n, rn[:smo + 0.9km] >> 0.5lt, "RNX");
        track(rn[:smo + 0.89km, :tvi - 0.49sw]);
    }

    with link = "point.dk.Tvillinggårde", railway = :station {
        track(rn[:tvi - 0.5sw, :tvi + 0.5sw]);
        marker(:left :de.hp, rn[:tvi] << 0.5lt);
        slabel(:top, rn[:tvi] << 0.5lt << 1sh + (-3dt, -0.4dt),
            "Tvillinggårde"
        );
    }

    with link = "line.dk.RNX" {
        track(rn[:tvi + 0.49sw, :aki.ya - 0.49seg]);
        track(:station, rn[:aki.ya - 0.5seg, :aki.ya + 01.dl]);
        track(:lor, rn[:aki.ya, :aki - 0.49sw]);
    }

    with link = "point.dk.Aakirkeby", railway = :station {
        track(rn[:aki - 0.5sw, :aki + 0.5sw + 1.1dl]);
        track(
                rn[:aki - 0.5sw, :aki + 0.5sw] << 1ls << 1lt
            --  rn[:aki + 0.5sw + 1dl, :aki + 0.5sw + 1.1dl]
        );
        marker(:right :de.bf, rn[:aki] >> 0.5lt);
        slabel(:bottom, rn[:aki] >> 0.5lt >> 1sh + (-4.5dt, 0.4dt),
            span(:bold, "Aakirkeby")
        );
    }

    with link = "line.dk.RNX" {
        track(rn[:aki - 0.1dl, :ugl - 0.49sw]);
    }

    with link = "point.dk.Ugleenge", railway = :station {
        track(rn[:ugl - 0.5sw, :ugl + 0.5sw]);
        marker(:left :de.bf, rn[:ugl] << 0.5lt);
        slabel(:ne, rn[:ugl] >> 0.5lt + (-1dt, -0.8dt),
            "Ugleenge"
        );
    }

    with link = "line.dk.RNX" {
        track(rn[:ugl + 0.49sw, :ugl + 1.51km]);
        line_label(:left:s, rn[:ugl + 1.5km] << 0.5lt, (0.5dt, 0dt), "RNX");
        track(rn[:ugl + 1.49km, :lan - 0.49sw]);
    }

    with link = "point.dk.Langemyregård", railway = :station {
        track(rn[:lan - 0.5sw, :lan + 0.5sw]);
        marker(:right :de.hp, rn[:lan] >> 0.5lt);
        slabel(:left, rn[:lan] >> 0.5lt >> 1sh + (-1.5dt, 1.3dt),
            "Langemyregård"
        );
    }

    with link = "line.dk.RNX" {
        track(rn[:lan + 0.49sw, :ped - 0.49sw]);
    }

    with link = "point.dk.Pedersker", railway = :station {
        track(rn[:ped - 0.5sw, :ped + 0.5sw]);
        marker(:right :de.bf, rn[:ped] >> 0.5lt);
        slabel(:bottom, rn[:ped] >> 0.5lt >> 1sh >> 0.2dt,
            "Pedersker"
        );
    }

    with link = "line.dk.RNX" {
        track(rn[:ped + 0.49sw, :pil - 0.49sw]);
    }

    with link = "point.dk.Pilemølle", railway = :station {
        track(rn[:pil - 0.5sw, :pil + 0.5sw]);
        marker(:left :de.hp, rn[:pil] << 0.5lt);
        slabel(:top, rn[:pil] << 0.5lt << 1sh + (-1dt, -0.3dt),
            "Pilemølle"
        );
    }

    with link = "line.dk.RNX" {
        track(rn[:pil + 0.49sw, :bod - 0.49sw]);
    }

    with link = "point.dk.Bodilsker", railway = :station {
        track(rn[:bod - 0.5sw, :bod + 0.5sw]);
        marker(:left :de.bf, rn[:bod] << 0.5lt);
        slabel(:top, rn[:bod] << 0.5lt << 1sh << 0.3dt,
            "Bodilsker"
        );
    }

    with link = "line.dk.RNX" {
        track(rn[:bod + 0.49sw, :kan - 0.49sw]);
    }

    with link = "point.dk.Kannikegård", railway = :station {
        track(rn[:kan - 0.5sw, :kan + 0.5sw]);
        marker(:right :de.bf, rn[:kan] >> 0.5lt);
        slabel(:bottom, rn[:kan] >> 0.5lt >> 1sh >> 0.3dt,
            " Kannikegård*"
        );
    }

    with link = "line.dk.RNX" {
        track(rn[:kan + 0.49sw, :bal - 0.49sw]);
    }

    with link = "point.dk.Balke-Strand", railway = :station {
        track(rn[:bal - 0.5sw, :bal + 0.5sw]);
        marker(:left :de.hp, rn[:bal] << 0.5lt);
        slabel(:right, rn[:bal] >> 0.5lt + (1.8dt, 1.3dt),
            "Balke Strand*"
        );
    }

    with link = "line.dk.RNX" {
        track(rn[:bal + 0.49sw, :bal + 1.51km]);
        line_label(:left:e, rn[:bal + 1.5km] << 0.5lt, (0dt, -0.3dt), "RNX");
        track(rn[:bal + 1.49km, :nek - 0.49sw]);
    }

    with link = "point.dk.", railway = :station {
        track(rn[:nek - 0.5sw, :nek + 0.5sw]);
        marker(:left :de.bf, rn[:nek] << 0.5lt);
        slabel(:right, rn[:nek] >> 0.5lt + (1dt, 1dt),
            span(:bold, "Neksø")
        );
